101	async function loadRawYaml(filePath: string): Promise<Record<string, unknown>> {
102	  if (!existsSync(filePath)) return {};
103	  const raw = await readFile(filePath, 'utf8');
104	  const parsed: unknown = yaml.load(raw);
105	  if (parsed === null || parsed === undefined) return {};
106	  if (typeof parsed !== 'object' || Array.isArray(parsed)) return {};
107	  return parsed as Record<string, unknown>;
108	}
109	
110	/**
111	 * Load a persona YAML file and return it as a plain metadata record.
112	 * The `name` field is derived from the filename stem when absent.
113	 *
114	 * @param yamlPath  Absolute path to the persona YAML file
115	 * @returns         Merged metadata record ready for context building
116	 */
117	async function loadPersonaYaml(yamlPath: string): Promise<Record<string, unknown>> {
118	  const raw = await readFile(yamlPath, 'utf8');
119	  const parsed: unknown = yaml.load(raw);
120	
121	  if (parsed === null || parsed === undefined || typeof parsed !== 'object' || Array.isArray(parsed)) {
122	    throw new Error(`buildPersona: expected a YAML object in "${yamlPath}"`);
123	  }
124	
125	  const record = parsed as Record<string, unknown>;
126	
127	  // Derive name from filename stem if not present in YAML
128	  if (!record['name']) {
129	    record['name'] = path.basename(yamlPath, '.yaml');
130	  }
131	
132	  return record;
133	}
