135	/**
136	 * Resolve the output directory for a given target from a suite configuration.
137	 *
138	 * Resolution order (first match wins):
139	 *   1. `suiteConfig.outputDirs[definition.outputDirKey]` — generic map, takes precedence.
140	 *   2. `suiteConfig.outVscode` — deprecated fallback for the built-in 'vscode' key.
141	 *   3. `suiteConfig.outClaudeCode` — deprecated fallback for the built-in 'claude-code' key.
142	 *
143	 * The lookup key is `definition.outputDirKey` when a registry definition is
144	 * provided, falling back to the raw `target` name for unregistered targets
145	 * (where `outputDirKey` equals the name by convention).
146	 *
147	 * @param target      The build target name.
148	 * @param suiteConfig The suite configuration to resolve from.
149	 * @param definition  Optional registry definition for the target. When present,
150	 *                    `definition.outputDirKey` is used as the output dir map key.
151	 * @returns           Resolved output directory path.
152	 * @throws {Error}    When no output directory is configured for the target.
153	 */
154	function resolveOutputDir(
155	  target: string,
156	  suiteConfig: SuiteConfig,
157	  definition?: TargetDefinition,
158	): string {
159	  // Build a merged map: deprecated named fields provide the base, outputDirs overrides.
160	  const merged: Record<string, string> = {};
161	  if (suiteConfig.outVscode) merged['vscode'] = suiteConfig.outVscode;
162	  if (suiteConfig.outClaudeCode) merged['claude-code'] = suiteConfig.outClaudeCode;
163	  if (suiteConfig.outputDirs) Object.assign(merged, suiteConfig.outputDirs);
164	
165	  // Use outputDirKey from the registry definition when available, falling back
166	  // to the target name for unregistered targets where outputDirKey === name.
167	  const lookupKey = definition?.outputDirKey ?? target;
168	  const dir = merged[lookupKey];
169	  if (dir) return dir;
170	
171	  throw new Error(
172	    `buildPersona: no output directory configured for target "${target}". ` +
173	      `Add outputDirs['${lookupKey}'] to the suite config, or, for the built-in ` +
174	      `targets, provide the outVscode / outClaudeCode fields.`,
175	  );
176	}
