178	/**
179	 * Pre-scan all suites and build a cross-suite agent name map.
180	 *
181	 * For each persona across all configured suites, creates a context variable:
182	 *   key:   `agent_` + slug (hyphens → underscores)
183	 *   value: `"<name> v<version>"`
184	 *
185	 * Slug is taken from the persona YAML's `slug` field, falling back to the
186	 * filename stem. Version falls back to the suite's `default_version`, then
187	 * to `'0.0.0'`.
188	 *
189	 * @param config  Top-level BuildConfig with all suite definitions
190	 * @returns       Map of agent variable keys to display strings
191	 */
192	async function buildAgentNameMap(
193	  config: BuildConfig,
194	): Promise<Record<string, string>> {
195	  const agentMap: Record<string, string> = {};
196	
197	  for (const [, suiteConfig] of Object.entries(config.suites)) {
198	    const metaSubdir = suiteConfig.metaSubdir ?? 'meta';
199	    const sharedYamlPath = path.join(suiteConfig.srcDir, metaSubdir, '_shared.yaml');
200	    const sharedMeta = await loadRawYaml(sharedYamlPath);
201	    const defaultVersion =
202	      typeof sharedMeta['default_version'] === 'string'
203	        ? sharedMeta['default_version']
204	        : '0.0.0';
205	
206	    const personaYamls = await discoverSuitePersonaYamls(suiteConfig);
207	
208	    for (const yamlPath of personaYamls) {
209	      const persona = await loadPersonaYaml(yamlPath);
210	
211	      const slug =
212	        typeof persona['slug'] === 'string'
213	          ? persona['slug']
214	          : path.basename(yamlPath, '.yaml');
215	
216	      const name =
217	        typeof persona['name'] === 'string'
218	          ? persona['name']
219	          : slug;
220	
221	      const version =
222	        typeof persona['version'] === 'string'
223	          ? persona['version']
224	          : defaultVersion;
225	
226	      const underscoredSlug = slug.replace(/-/g, '_');
227	      const key = `agent_${underscoredSlug}`;
228	      agentMap[key] = `${name} v${version}`;
229	
230	      const slugKey = `agent_slug_${underscoredSlug}`;
231	      agentMap[slugKey] = slug;
232	    }
233	  }
234	
235	  return agentMap;
236	}
