238	/**
239	 * Build the merged template context for a single persona.
240	 *
241	 * Merge order (later values win):
242	 *   1. configVariables (lowest priority — global BuildConfig.variables)
243	 *   2. suiteVariables  (suite-level SuiteConfig.variables)
244	 *   3. sharedMeta      (parsed _shared.yaml fields)
245	 *   4. personaMeta     (per-persona YAML fields)
246	 *   5. derived/computed fields (version fallback, tools serialisation, etc.)
247	 *   6. agentMap entries (only for keys not already present)
248	 *   7. target flags    (injected last; always win)
249	 *
250	 * @param personaMeta      Per-persona YAML as a plain record

251	 * @param sharedMeta       Parsed `_shared.yaml` fields
252	 * @param agentMap         Cross-suite agent name map (injected by build())
253	 * @param target           The current build target (forwarded to plugins)
254	 * @param registry         Target registry for context-flag injection
255	 * @param configVariables  Optional global variables from BuildConfig.variables
256	 *                         (lowest precedence; overridden by all other layers)
257	 * @param suiteVariables   Optional suite-level variables from SuiteConfig.variables
258	 *                         (overrides configVariables; overridden by sharedMeta and personaMeta)
259	 * @returns                Merged rendering context
260	 */
261	function buildContext(
262	  personaMeta: Record<string, unknown>,
263	  sharedMeta: Record<string, unknown>,
264	  agentMap: Record<string, string> = {},
265	  target?: TargetType,
266	  registry?: TargetRegistry,
267	  configVariables?: Record<string, unknown>,
268	  suiteVariables?: Record<string, unknown>,
269	): Record<string, unknown> {
270	  const version =
